from collections import Counter, deque

def transform(grid):
    h,w=len(grid),len(grid[0])
    counts=Counter(v for row in grid for v in row)
    background=counts.most_common(1)[0][0]
    seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
        col=grid[r][c]
        if col in (0,background) or (r,c) in seen: continue
        q=[(r,c)];seen.add((r,c));cells=[]
        while q:
          y,x=q.pop();cells.append((y,x))
          for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
            if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==col:
              seen.add((yy,xx));q.append((yy,xx))
        ys=[y for y,x in cells];xs=[x for y,x in cells]
        comps.append((col,cells,min(ys),max(ys),min(xs),max(xs)))
    out=[row[:] for row in grid]
    for i,a in enumerate(comps):
      color,acells,at,ab,al,ar=a
      for b in comps[i+1:]:
        bc,bcells,bt,bb,bl,br=b
        if bc!=color: continue
        # horizontal connector if same row span
        if at==bt and ab==bb and (ar < bl or br < al):
          for y in range(at,ab+1):
            left,right=(ar,bl) if ar<bl else (br,al)
            for x in range(left+1,right):
              if out[y][x]==0:out[y][x]=color
        # vertical connector if same column span
        if al==bl and ar==br and (ab < bt or bb < at):
          for x in range(al,ar+1):
            top,bottom=(ab,bt) if ab<bt else (bb,at)
            for y in range(top+1,bottom):
              if out[y][x]==0:out[y][x]=color
    return out

